package io.github.chronicle.core.client;

import io.github.chronicle.core.menu.CoreMenuModel;
import io.github.chronicle.core.menu.EncounterEditorForm;
import net.minecraft.client.gl.RenderPipelines;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.gui.screen.Screen;
import net.minecraft.client.gui.tooltip.Tooltip;
import net.minecraft.client.gui.widget.ButtonWidget;
import net.minecraft.client.gui.widget.TextFieldWidget;
import net.minecraft.text.Text;
import net.minecraft.util.Identifier;

import java.util.*;

/** Three-step local encounter draft; saving never spawns or previews an entity. */
public final class EncounterEditorScreen extends Screen {
    private static final Identifier POPUP=Identifier.ofVanilla("popup/background");
    public interface Transport {void catalog(CatalogAddPopup popup,String kind,String query,int page);void save(EncounterEditorForm form);}
    private enum Page { BASICS,MEMBERS,SPAWN }
    private final CoreMenuScreen parent;private final Transport transport;private final long openingToken,groupRevision,bindingRevision;private final boolean creating;private Page page=Page.BASICS;private String id,label,description,targetKind,siteId,siteLabel,problem="";private long siteRevision;private boolean targetCurrent,stale;private final List<EncounterEditorForm.Member> members=new ArrayList<>();private int memberOffset,editing=-1;private TextFieldWidget idField,labelField,descriptionField,countField;private CatalogAddPopup popup;private String pickerKind="";
    public EncounterEditorScreen(CoreMenuScreen parent,EncounterEditorForm initial,Transport transport){super(Text.literal(initial.creating()?"Create encounter group":"Edit encounter group"));this.parent=Objects.requireNonNull(parent);this.transport=Objects.requireNonNull(transport);openingToken=parent.state().token();groupRevision=initial.groupRegistryRevision();bindingRevision=initial.bindingRegistryRevision();creating=initial.creating();id=initial.id();label=initial.label();description=initial.description();members.addAll(initial.members());targetKind=initial.targetKind();siteId=initial.siteId();siteLabel=initial.siteLabel();siteRevision=initial.siteRevision();targetCurrent=initial.current();problem=initial.problem();}
    public CoreMenuScreen parentMenu(){return parent;}public long openingToken(){return openingToken;}
    public String pageForTest(){return page.name();}
    public EncounterEditorForm valuesForTest(){retain();return form();}
    public void setDraftForTest(String field,String value){TextFieldWidget target=switch(field){case "id"->idField;case "label"->labelField;case "description"->descriptionField;default->throw new IllegalArgumentException("Unknown encounter draft field: "+field);};if(target==null)throw new IllegalStateException("Encounter draft field is not visible: "+field);target.setText(value);}
    public boolean pressForTest(String label){for(var child:children())if(child instanceof ButtonWidget button&&button.visible&&button.active&&button.getMessage().getString().equals(label)){button.onPress(new net.minecraft.client.input.MouseInput(0,0));return true;}return false;}
    public void serverUpdated(CoreMenuModel.View view){if(view.token()!=openingToken||!view.operator()||!view.editable()||!view.editing()||!view.hold().isBlank()){stale=true;if(popup!=null)popup.markStale();}if(popup!=null&&view.picker()!=null&&view.picker().kind().equals(pickerKind))popup.replacePage(view.picker());if(client.currentScreen==this)clearAndInit();}
    public void rejected(String message,boolean stale){problem=message==null?"The server rejected this encounter draft.":message;this.stale|=stale;if(popup!=null&&this.stale)popup.markStale();if(client.currentScreen==this)clearAndInit();}
    @Override protected void init(){retain();clearChildren();idField=labelField=descriptionField=countField=null;int w=Math.min(440,Math.max(240,width-24)),x=(width-w)/2,y=Math.max(6,(height-240)/2+6);button("<",x,y+22,26,()->move(-1),"Previous section",usable()&&page.ordinal()>0);button(title()+" "+(page.ordinal()+1)+"/3",x+30,y+22,w-60,()->{},"Saving definitions never spawns entities",false);button(">",x+w-26,y+22,26,()->move(1),"Next section",usable()&&page.ordinal()<2);switch(page){case BASICS->basics(x,y,w);case MEMBERS->members(x,y,w);case SPAWN->spawn(x,y,w);}button("Cancel",x,y+206,92,()->client.setScreen(parent),"Discard this local draft",true);button(creating?"Create group":"Save edits",x+96,y+206,w-96,this::save,"Save composition and exact map binding; spawn nothing",usable()&&valid());}
    private void basics(int x,int y,int w){int row=y+60;if(creating){idField=field(x,row,w,"Group ID",id,128,value->id=value);row+=34;}labelField=field(x,row,w,"Name",label,80,value->label=value);descriptionField=field(x,row+34,w,"Organizer description",description,512,value->description=value);}
    private void members(int x,int y,int w){button(editing<0?"Add entity…":"Done editing",x,y+60,w-46,()->{if(editing>=0){retain();editing=-1;clearAndInit();}else open("ENCOUNTER_ENTITY");},"Choose from the server allowlist",usable()&&(editing>=0||members.size()<16));arrows(x,y,w);memberOffset=Math.clamp(memberOffset,0,Math.max(0,members.size()-4));for(int i=0;i<4&&memberOffset+i<members.size();i++){int index=memberOffset+i,row=y+84+i*22;var member=members.get(index);button(shorten(member.label()+" × "+member.count(),28),x,row,w-112,()->{editing=index;clearAndInit();},member.problem().isBlank()?member.entityType():member.problem(),usable());button("-",x+w-108,row,24,()->change(index,-1),"Decrease count",usable()&&member.count()>1);button("+",x+w-82,row,24,()->change(index,1),"Increase count",usable()&&member.count()<32&&total()<64);button("Remove",x+w-56,row,56,()->{members.remove(index);editing=-1;clearAndInit();},"Remove member",usable());}if(editing>=0&&editing<members.size()){countField=field(x,y+174,w,"Selected count (1-32)",Integer.toString(members.get(editing).count()),2,value->{try{int count=Integer.parseInt(value);var old=members.get(editing);if(count>=1&&count<=32&&total()-old.count()+count<=64)members.set(editing,new EncounterEditorForm.Member(old.entityType(),old.label(),count,old.current(),old.problem()));}catch(NumberFormatException ignored){}});}}
    private void spawn(int x,int y,int w){int half=(w-4)/2;button(choice("POINT")+"Point",x,y+60,half,()->chooseKind("POINT"),"Use an existing map Point",usable());button(choice("REGION")+"Region",x+half+4,y+60,w-half-4,()->chooseKind("REGION"),"Use an existing map Region",usable());if(!targetKind.isBlank())button(siteId.isBlank()?"Choose "+targetKind.toLowerCase(Locale.ROOT)+"…":"Target: "+shorten(siteLabel.isBlank()?siteId:siteLabel,34),x,y+88,w,()->open("ENCOUNTER_"+targetKind),targetCurrent?"Exact map revision "+siteRevision:problem,usable());}
    private void chooseKind(String kind){if(!kind.equals(targetKind)){targetKind=kind;siteId=siteLabel="";siteRevision=0;targetCurrent=false;}clearAndInit();}
    private void open(String kind){retain();pickerKind=kind;popup=new CatalogAddPopup(this,Text.literal(kind.equals("ENCOUNTER_ENTITY")?"Add entity":"Choose "+targetKind.toLowerCase(Locale.ROOT)),false,new CatalogAddPopup.Owner(){@Override public void requestPage(CatalogAddPopup picker,String query,int page){transport.catalog(picker,kind,query,page);}@Override public String validate(CoreMenuModel.Entry entry,String quantity){return kind.equals("ENCOUNTER_ENTITY")&&members.stream().anyMatch(member->member.entityType().equals(entry.id()))?"That entity type is already in this group.":"";}@Override public void add(CoreMenuModel.Entry entry,String quantity){popup=null;if(kind.equals("ENCOUNTER_ENTITY"))members.add(new EncounterEditorForm.Member(entry.id(),entry.label(),1,true,""));else{siteId=entry.id();siteLabel=entry.label();siteRevision=entry.revision();targetCurrent=true;}clearAndInit();}@Override public void cancel(){popup=null;clearAndInit();}@Override public void serverUpdated(CatalogAddPopup picker,CoreMenuModel.View view){EncounterEditorScreen.this.serverUpdated(view);}});client.setScreen(popup);}
    private void save(){retain();if(!valid())return;transport.save(form());}
    private EncounterEditorForm form(){return new EncounterEditorForm(groupRevision,bindingRevision,id,label,description,members,targetKind,siteId,siteLabel,siteRevision,targetCurrent,problem,creating);}
    private boolean valid(){return !id.isBlank()&&!label.isBlank()&&!members.isEmpty()&&members.stream().allMatch(EncounterEditorForm.Member::current)&&!targetKind.isBlank()&&!siteId.isBlank()&&targetCurrent&&total()<=64;}
    private int total(){return members.stream().mapToInt(EncounterEditorForm.Member::count).sum();}private void change(int index,int amount){var old=members.get(index);int count=old.count()+amount;if(count>=1&&count<=32&&total()-old.count()+count<=64)members.set(index,new EncounterEditorForm.Member(old.entityType(),old.label(),count,old.current(),old.problem()));clearAndInit();}
    private void arrows(int x,int y,int w){button("↑",x+w-44,y+60,20,()->{memberOffset--;clearAndInit();},"Earlier members",usable()&&memberOffset>0);button("↓",x+w-20,y+60,20,()->{memberOffset++;clearAndInit();},"Later members",usable()&&memberOffset+4<members.size());}
    private TextFieldWidget field(int x,int y,int w,String hint,String value,int max,java.util.function.Consumer<String> changed){addDrawable((context,mouseX,mouseY,delta)->context.drawTextWithShadow(textRenderer,Text.literal(hint),x,y,0xFFCCCCCC));TextFieldWidget field=addDrawableChild(new TextFieldWidget(textRenderer,x,y+11,w,18,Text.literal(hint)));field.setMaxLength(max);field.setText(value);field.setChangedListener(changed);field.active=usable();return field;}
    private void retain(){if(idField!=null)id=idField.getText();if(labelField!=null)label=labelField.getText();if(descriptionField!=null)description=descriptionField.getText();}
    private void move(int direction){retain();page=Page.values()[page.ordinal()+direction];editing=-1;clearAndInit();}private boolean usable(){return !stale;}private String title(){return switch(page){case BASICS->"Basics";case MEMBERS->"Members";case SPAWN->"Spawn";};}private String choice(String kind){return targetKind.equals(kind)?"● ":"○ ";}
    private void button(String label,int x,int y,int w,Runnable action,String tip,boolean active){ButtonWidget button=addDrawableChild(ButtonWidget.builder(Text.literal(label),ignored->action.run()).dimensions(x,y,w,18).build());button.active=active;if(!tip.isBlank())button.setTooltip(Tooltip.of(Text.literal(tip)));}
    private static String shorten(String value,int max){return value.length()<=max?value:value.substring(0,Math.max(0,max-1))+"…";}
    @Override public void render(DrawContext context,int mouseX,int mouseY,float delta){int w=Math.min(440,Math.max(240,width-24)),x=(width-w)/2,y=Math.max(6,(height-240)/2+6);context.drawGuiTexture(RenderPipelines.GUI_TEXTURED,POPUP,x-8,y-8,w+16,240);context.drawCenteredTextWithShadow(textRenderer,getTitle(),width/2,y+4,0xFFFFFFFF);String status=stale?"Server state changed; close and reopen.":problem;if(page!=Page.MEMBERS||editing<0)context.drawTextWithShadow(textRenderer,Text.literal(textRenderer.trimToWidth(status==null?"":status,w)),x,y+190,stale?0xFFFF7777:0xFFAAAAAA);super.render(context,mouseX,mouseY,delta);}
    @Override public void close(){client.setScreen(parent);}
}
